def main():
    lines = ["# fact_check.md — 逐句事实核查（《ELIZA》，\"AI 的历史\"系列第 1 期）", "",
             "**核查日期：2026-10-14。** 每一行的“旁白”列由 `script.py` 自动抽出，与成片字幕、配音一字不差（读法差异见 `script.py` 的 `SPOKEN`）。", "",
             "## 方法与局限（请先读）",
             "- 本容器的网络只放行 WebSearch（只返回摘要）和少数代码托管域名；**无法打开 CACM 原论文、1976 年原书、OpenAI/FTC/Pew/Common Sense 原站**。",
             "- 因此：① 论文与书的原文，依据 A. Hay 在 GitHub 的转录与引用（他逐字转录了论文附录脚本与对话，并引用了书中带页码的整段原文），再与多个检索摘要交叉；② 数据类事实，依据多家媒体/机构的检索摘要交叉；③ 凡只有一处来源的，在“结论”里标了“二手转引”或“单一来源”。",
             "- 屏幕上的引语卡片（0.3、2.2、2.6、3.4、3.7、5.7、6.2）逐字取自上述转录/引述；其中 5.7 的 OpenAI 原句经 TechCrunch、NBC 等多家一致引述。",
             "- 结论图例：核实 / 核实（二手转引） / 转述（原意核实） / 自行计算 / 观点 / 描述。没有任何一句被标为“未核实”；核实不了的句子已在写稿阶段删除或改写（见文末）。", "",
             "| 句号 | 旁白（= 字幕，一字不差） | 核对说明 | 来源名 + 链接 + 日期 | 结论 |", "|---|---|---|---|---|"]
    for seg, lns in SEGMENTS.items():
        for lid, en, pre in lns:
            note, keys, verdict = ROWS[lid]
            srcs = "<br>".join(f"{SRC[k][0]} — <{SRC[k][1]}> — {SRC[k][2]}" for k in keys) or "—"
            en_ = en.replace("|", "\\|")
            lines.append(f"| {lid} | {en_} | {note} | {srcs} | {verdict} |")
    lines += ["", "## 写稿阶段删掉或改写的说法（因核实不了或说得过满）",
              "- 删：Carl Sagan 1975 年关于“电脑心理治疗终端”的引语——检索未能核实出处与原文，**不使用**。",
              "- 删：加州 SB 243（陪伴型聊天机器人法）——条款细节（提醒频率、适用对象）未能核实，且检索摘要提到该法有诉讼/禁令的说明，**不讲**；改用已核实的 Illinois 法案与 FTC 调查。",
              "- 删：“Weizenbaum 的本意是用 ELIZA 证明交流很肤浅”——2024 年 Shrager 的 arXiv 论文《ELIZA Reinterpreted》主张 ELIZA 本是研究平台，**意图有争议**，旁白只讲他写了什么、说了什么，不断言动机。",
              "- 改：4.2 由 “nobody could read” 改为 “the public could not read”（档案馆人员能看到）。",
              "- 改：1.7 由 “Almost everything” 改为 “Most of what”（逐条计数 12/15）。",
              "- 改：5.6 由 “could only echo” 改为 “mostly echoed”；6.2 由 “was never” 改为 “was not”（避免绝对化）。",
              "- 改：第 3 分钟左右的转折用论文开头 “magic crumbles away” 的内容，不再声称这是他写论文的目的。", "",
              "## 已知局限（诚实记录）",
              "- 1.1 “room-sized”是描述，不是来源原话。",
              "- 4.4 的文件夹标签只有 Hay 一处记载。",
              "- 2.9 的精神科医生一句，书页原文未能直接看到，依据 Wikipedia 与 Gordon College 讲义转引。",
              "- 5.8 的 GPT-4o 恢复范围各家说法略有不同（仅 Plus / 付费用户），旁白只说 “as an option”。",
              "- 数据类事实以 2026-10-14 前可查到的最新数据为准（如 ChatGPT 周活为 2025-10 数字，Pew 为 2026-02 调查）。"]
    open("fact_check.md", "w", encoding="utf-8").write("\n".join(lines) + "\n")
    print("rows", sum(len(l) for l in SEGMENTS.values()))

if __name__ == "__main__":
    main()
